// ---- TWIN: the gates' paired real-tree twins on wb-tz2.17, checked in (wb-tz2.21's acceptance) -------------------------------
// Each twin plants its gate's page edit over the subject, verbatim but for lg- file names, and pins what these readers read in
// it. Under the gate's hollowing the page reads otherwise, so the row reds: a fail-open twin reads loud here (the receipt
// helper a carrier, a load that does not resolve, the census tier's config broken), a fail-closed twin reads quiet (no pin).

const CARRIER = "wb-tz2.21";
interface TwinRow {
  readonly id: string;
  /** The bead whose refusal's PREP authored the twin. */
  readonly bead: typeof BEAD | typeof CARRIER;
  /** That refusal (wb-tz2.17 #3: gate-prep-1, O:1634; wb-tz2.17 #4: gate-prep-12, O:1743; wb-tz2.21 #1: gate-prep-14, O:1789;
   * wb-tz2.21 #2: gate-prep-12, O:1832; wb-tz2.21 #3: gate-prep-9, O:1884; wb-tz2.21 #4: gate-prep-9, O:1924, checked in by
   * wb-cl20). */
  readonly refusal: 1 | 2 | 3 | 4;
  /** The gate member the twin realizes. */
  readonly member: string;
  readonly edits: readonly Edit[];
  readonly pins: GatePins;
}
const SDK = "node_modules/@hyperunix/sdk/dist/index.js";
const hxTwin = (line: string): Edit => ({ file: HX, text: `\n${line}\n`, append: true });
/** The cited suite's IMPORT reading when its receipt helper holds `line`, a route: the helper is a second load reaching vitest. */
const carrierPins = (line: string, route: string): GatePins => ({
  import: `IMPORT <2 loads resolve to a vitest module or a carrier: import declaration 'vitest' at line {{L:${SUITE}|${VITEST_IMPORT}}} (vitest (vitest)), import declaration './helpers/hx-live-receipt.js' at line {{L:${SUITE}|${RECEIPT_IMPORT}}} (carrier (${HX}:{{L:${HX}|${line}}} holds a ${route}))>`,
});
const carrierTwin = (id: string, refusal: 3 | 4, member: string, line: string, route: string): TwinRow => ({ id, bead: BEAD, refusal, member, edits: [hxTwin(line)], pins: carrierPins(line, route) });
const quietTwin = (id: string, member: string, edit: Edit): TwinRow => ({ id, bead: BEAD, refusal: 4, member, edits: [edit], pins: {} });
/** A twin of refusal #1 on wb-tz2.21 (gate-prep-14, O:1789; its make_twins_gp14 spec, verbatim but for lg- file names). */
const carrierRefusal1 = (id: string, member: string, edits: readonly Edit[], pins: GatePins): TwinRow => ({ id, bead: CARRIER, refusal: 1, member, edits, pins });
/** A twin of refusal #2 on wb-tz2.21 (gate-prep-12, O:1832; its twins/ pages, verbatim): the census config or the cited suite edited. */
const carrierRefusal2 = (id: string, member: string, edits: readonly Edit[], pins: GatePins): TwinRow => ({ id, bead: CARRIER, refusal: 2, member, edits, pins });
/** A twin of refusal #3 on wb-tz2.21 (gate-prep-9, O:1884; its twins/ pages, verbatim): the cited suite or the receipt helper edited. */
const carrierRefusal3 = (id: string, member: string, edits: readonly Edit[], pins: GatePins): TwinRow => ({ id, bead: CARRIER, refusal: 3, member, edits, pins });
/** A twin of refusal #4 on wb-tz2.21 (gate-prep-9, O:1924; its twins/ pages, verbatim), checked in by wb-cl20 (R-B438): the cited
 * suite edited. */
const carrierRefusal4 = (id: string, member: string, edits: readonly Edit[], pins: GatePins): TwinRow => ({ id, bead: CARRIER, refusal: 4, member, edits, pins });
const suiteTwin = (line: string): Edit => ({ file: SUITE, old: RECEIPT_IMPORT, text: `${RECEIPT_IMPORT}\n${line}` });
const configTwin = (line: string): Edit => ({ file: CENSUS_CONFIG, old: DEFINE_IMPORT, text: line });
